namespace CafeOrdering.Models;
public class Order { public int Id { get; set; } public string OrderNumber { get; set; } = Guid.NewGuid().ToString("N")[..10].ToUpper(); public string CustomerName { get; set; } = ""; public string Phone { get; set; } = ""; public string Email { get; set; } = ""; public string Location { get; set; } = ""; public string LocationDetails { get; set; } = ""; public decimal Total { get; set; } public string Status { get; set; } = "Pending"; public string VerificationToken { get; set; } = ""; public DateTime TokenExpiresAt { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime? ConfirmedAt { get; set; } public bool TelegramSent { get; set; } public List<OrderItem> Items { get; set; } = new(); }
public class OrderItem { public int Id { get; set; } public int OrderId { get; set; } public int ProductId { get; set; } public string ProductName { get; set; } = ""; public decimal UnitPrice { get; set; } public int Quantity { get; set; } public Order? Order { get; set; } }
